'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { useAuth } from '@/context/AuthContext';
import { Calendar, Zap, Plus, X } from 'lucide-react';

const DAYS = ['', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const DAY_SHORT = ['', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

export default function TimetablePage() {
    const { user } = useAuth();
    const [batches, setBatches] = useState<any[]>([]);
    const [selectedBatch, setSelectedBatch] = useState('');
    const [timetable, setTimetable] = useState<any>({ slots: [], grid: {} });
    const [periods, setPeriods] = useState<any[]>([]);
    const [showManual, setShowManual] = useState(false);
    const [subjects, setSubjects] = useState<any[]>([]);
    const [faculty, setFaculty] = useState<any[]>([]);
    const [classrooms, setClassrooms] = useState<any[]>([]);
    const [slotForm, setSlotForm] = useState({
        subject_id: '', faculty_id: '', classroom_id: '', day_of_week: 1, period_number: 1,
        start_time: '09:00', end_time: '09:50', slot_type: 'lecture',
    });
    const [generating, setGenerating] = useState(false);
    const [message, setMessage] = useState('');
    const isAdmin = user?.role === 'admin';

    useEffect(() => { loadSetup(); }, []);

    useEffect(() => {
        if (selectedBatch) loadTimetable();
    }, [selectedBatch]);

    const loadSetup = async () => {
        const [b, p] = await Promise.all([
            api.get<any[]>('/api/institution/batches').catch(() => ({ success: false, data: [] } as any)),
            api.get<any[]>('/api/institution/period-templates').catch(() => ({ success: false, data: [] } as any)),
        ]);
        if (b.success) {
            setBatches(b.data);
            if (b.data.length > 0) setSelectedBatch(b.data[0].id);
        }
        if (p.success) setPeriods(p.data.filter((pp: any) => !pp.is_break));

        if (isAdmin) {
            const [s, f, c] = await Promise.all([
                api.get<any[]>('/api/admin/subjects').catch(() => ({ success: false, data: [] } as any)),
                api.get<any[]>('/api/admin/users').catch(() => ({ success: false, data: [] } as any)),
                api.get<any[]>('/api/institution/classrooms').catch(() => ({ success: false, data: [] } as any)),
            ]);
            if (s.success) setSubjects(s.data);
            if (f.success) setFaculty(f.data.filter((u: any) => u.role === 'faculty' && u.is_active));
            if (c.success) setClassrooms(c.data);
        }
    };

    const loadTimetable = async () => {
        try {
            const res = await api.get<any>(`/api/institution/timetable/batch/${selectedBatch}`);
            if (res.success) setTimetable(res.data);
        } catch { }
    };

    const handleGenerate = async () => {
        setGenerating(true);
        setMessage('');
        try {
            const res = await api.post<any>('/api/institution/timetable/generate', {
                batch_id: selectedBatch,
                force_regenerate: true,
            });
            if (res.success) {
                setMessage(`✓ Generated ${res.data.allocated_slots} slots`);
                loadTimetable();
            }
        } catch (err: any) {
            setMessage(`✗ ${err.message}`);
        }
        setGenerating(false);
    };

    const handleAddSlot = async () => {
        try {
            await api.post('/api/institution/timetable/slots', {
                batch_id: selectedBatch,
                ...slotForm,
                day_of_week: +slotForm.day_of_week,
                period_number: +slotForm.period_number,
            });
            setShowManual(false);
            loadTimetable();
        } catch (err: any) {
            setMessage(`✗ ${err.message}`);
        }
    };

    const handleDeleteSlot = async (slotId: string) => {
        try {
            await api.delete(`/api/institution/timetable/slots/${slotId}`);
            loadTimetable();
        } catch { }
    };

    // Build grid for display
    const maxPeriod = periods.length > 0 ? Math.max(...periods.map(p => p.period_number)) : 6;
    const periodNums = Array.from({ length: maxPeriod }, (_, i) => i + 1);
    const periodMap: Record<number, any> = {};
    periods.forEach(p => { periodMap[p.period_number] = p; });

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <div>
                    <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins' }}>
                        {isAdmin ? 'Timetable Manager' : 'My Timetable'}
                    </h1>
                    <p style={{ fontSize: 14, color: '#5a6a72' }}>
                        {isAdmin ? 'Generate and manage timetables for batches' : 'View your class schedule'}
                    </p>
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                    {isAdmin && selectedBatch && (
                        <>
                            <button className="btn-secondary btn-sm" onClick={() => setShowManual(true)}>
                                <Plus size={14} /> Add Slot
                            </button>
                            <button className="btn-primary" onClick={handleGenerate} disabled={generating}>
                                <Zap size={16} /> {generating ? 'Generating...' : 'Auto-Generate'}
                            </button>
                        </>
                    )}
                </div>
            </div>

            {message && (
                <div style={{
                    padding: '10px 16px', borderRadius: 8, marginBottom: 16,
                    background: message.startsWith('✓') ? '#d1fae5' : '#fee2e2',
                    color: message.startsWith('✓') ? '#065f46' : '#991b1b', fontSize: 14,
                }}>{message}</div>
            )}

            {/* Batch Selector */}
            <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
                {batches.map(b => (
                    <button
                        key={b.id}
                        onClick={() => setSelectedBatch(b.id)}
                        style={{
                            padding: '8px 16px', borderRadius: 8, fontSize: 13, fontWeight: 600,
                            border: selectedBatch === b.id ? '2px solid #142B34' : '1px solid #e2e6ea',
                            background: selectedBatch === b.id ? '#142B34' : 'white',
                            color: selectedBatch === b.id ? 'white' : '#5a6a72',
                            cursor: 'pointer', transition: 'all 0.2s',
                        }}
                    >
                        {b.code}
                    </button>
                ))}
                {batches.length === 0 && (
                    <p style={{ color: '#8a9aa2', fontSize: 14 }}>No batches found. Create batches first.</p>
                )}
            </div>

            {/* Manual Add Form */}
            {showManual && isAdmin && (
                <div className="card" style={{ marginBottom: 20, padding: 20 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 12 }}>
                        <h3 style={{ fontSize: 14, fontWeight: 700 }}>Add Slot Manually</h3>
                        <button onClick={() => setShowManual(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}><X size={16} color="#8a9aa2" /></button>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12 }}>
                        <div className="form-group">
                            <label>Subject</label>
                            <select value={slotForm.subject_id} onChange={e => setSlotForm({ ...slotForm, subject_id: e.target.value })}>
                                <option value="">Select</option>
                                {subjects.map(s => <option key={s.id} value={s.id}>{s.name} ({s.code})</option>)}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Faculty</label>
                            <select value={slotForm.faculty_id} onChange={e => setSlotForm({ ...slotForm, faculty_id: e.target.value })}>
                                <option value="">Select</option>
                                {faculty.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Room</label>
                            <select value={slotForm.classroom_id} onChange={e => setSlotForm({ ...slotForm, classroom_id: e.target.value })}>
                                <option value="">Select</option>
                                {classrooms.map(c => <option key={c.id} value={c.id}>{c.name} ({c.code})</option>)}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Day</label>
                            <select value={slotForm.day_of_week} onChange={e => setSlotForm({ ...slotForm, day_of_week: +e.target.value })}>
                                {[1, 2, 3, 4, 5, 6].map(d => <option key={d} value={d}>{DAYS[d]}</option>)}
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Period</label>
                            <select value={slotForm.period_number} onChange={e => setSlotForm({ ...slotForm, period_number: +e.target.value })}>
                                {periodNums.map(p => <option key={p} value={p}>P{p} {periodMap[p] ? `(${periodMap[p].start_time})` : ''}</option>)}
                            </select>
                        </div>
                        <div className="form-group"><label>Start</label><input value={slotForm.start_time} onChange={e => setSlotForm({ ...slotForm, start_time: e.target.value })} /></div>
                        <div className="form-group"><label>End</label><input value={slotForm.end_time} onChange={e => setSlotForm({ ...slotForm, end_time: e.target.value })} /></div>
                        <div className="form-group" style={{ display: 'flex', alignItems: 'flex-end' }}>
                            <button className="btn-primary btn-sm" onClick={handleAddSlot}>Add Slot</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Timetable Grid */}
            {selectedBatch && (
                <div className="table-container" style={{ overflowX: 'auto' }}>
                    <table style={{ minWidth: 800 }}>
                        <thead>
                            <tr>
                                <th style={{ width: 80 }}>Day</th>
                                {periodNums.map(p => (
                                    <th key={p} style={{ textAlign: 'center', fontSize: 11 }}>
                                        <div>P{p}</div>
                                        {periodMap[p] && (
                                            <div style={{ fontWeight: 400, fontSize: 10, opacity: 0.7 }}>
                                                {periodMap[p].start_time?.slice(0, 5)} - {periodMap[p].end_time?.slice(0, 5)}
                                            </div>
                                        )}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {[1, 2, 3, 4, 5, 6].map(day => (
                                <tr key={day}>
                                    <td style={{ fontWeight: 700, fontSize: 13, background: '#f5f7f9' }}>{DAY_SHORT[day]}</td>
                                    {periodNums.map(p => {
                                        const slot = timetable.grid?.[day]?.[p];
                                        if (!slot) {
                                            return (
                                                <td key={p} style={{ textAlign: 'center', color: '#c4c6c9', fontSize: 20, padding: 12 }}>
                                                    —
                                                </td>
                                            );
                                        }
                                        return (
                                            <td key={p} style={{ padding: 8, position: 'relative' }}>
                                                <div style={{
                                                    background: '#f0f7ff', border: '1px solid #dbeafe', borderRadius: 8,
                                                    padding: '8px 10px', fontSize: 12, lineHeight: 1.5,
                                                }}>
                                                    <div style={{ fontWeight: 700, color: '#1e40af' }}>
                                                        {slot.subjects?.code || slot.subject_id?.slice(0, 6)}
                                                    </div>
                                                    <div style={{ color: '#5a6a72', fontSize: 11 }}>
                                                        {slot.users?.name || slot.faculty_id?.slice(0, 6)}
                                                    </div>
                                                    {slot.classrooms?.code && (
                                                        <div style={{ color: '#8a9aa2', fontSize: 10 }}>
                                                            {slot.classrooms.code}
                                                        </div>
                                                    )}
                                                    {isAdmin && (
                                                        <button
                                                            onClick={() => handleDeleteSlot(slot.id)}
                                                            style={{
                                                                position: 'absolute', top: 4, right: 4,
                                                                background: 'none', border: 'none', cursor: 'pointer',
                                                                color: '#DC2626', fontSize: 10, fontWeight: 700,
                                                                opacity: 0.5,
                                                            }}
                                                            onMouseEnter={e => { e.currentTarget.style.opacity = '1'; }}
                                                            onMouseLeave={e => { e.currentTarget.style.opacity = '0.5'; }}
                                                        >✕</button>
                                                    )}
                                                </div>
                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            )}

            {timetable.slots?.length === 0 && selectedBatch && (
                <div style={{ textAlign: 'center', padding: 40, color: '#8a9aa2' }}>
                    <Calendar size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p style={{ fontSize: 14 }}>No timetable generated yet.</p>
                    {isAdmin && <p style={{ fontSize: 13 }}>Click &quot;Auto-Generate&quot; or add slots manually.</p>}
                </div>
            )}
        </div>
    );
}
